'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { popcount32, nlz, isPow2, nextPow2, reverseBits32 } = require('./bits.js');

// Deterministic PRNG (xorshift32), same seed => same battery every run.
function makeRng(seed) {
  let s = seed >>> 0;
  return function () {
    s ^= s << 13; s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5; s >>>= 0;
    return s;
  };
}

function naivePopcount(x) {
  let c = 0;
  while (x) { c += x & 1; x >>>= 1; }
  return c;
}

test('popcount32 matches naive loop', () => {
  const rng = makeRng(0xc0ffee);
  for (let i = 0; i < 10000; i++) {
    const x = rng();
    assert.strictEqual(popcount32(x), naivePopcount(x), `x=${x}`);
  }
  for (let x = 0; x <= 0xffff; x++) {
    assert.strictEqual(popcount32(x), naivePopcount(x), `x=${x}`);
  }
});

test('nlz matches Math.clz32', () => {
  const rng = makeRng(0xbeef42);
  for (let i = 0; i < 10000; i++) {
    const x = rng();
    assert.strictEqual(nlz(x), Math.clz32(x), `x=${x}`);
  }
  for (let x = 0; x <= 0xffff; x++) {
    assert.strictEqual(nlz(x), Math.clz32(x), `x=${x}`);
  }
});

test('isPow2 basics', () => {
  assert.strictEqual(isPow2(0), false);
  assert.strictEqual(isPow2(1), true);
  assert.strictEqual(isPow2(2), true);
  assert.strictEqual(isPow2(3), false);
  assert.strictEqual(isPow2(6), false);
  assert.strictEqual(isPow2(0x80000000), true);
});

test('nextPow2 boundary cases', () => {
  assert.strictEqual(nextPow2(1), 1);
  assert.strictEqual(nextPow2(2), 2);
  assert.strictEqual(nextPow2(3), 4);
  assert.strictEqual(nextPow2(0x7fffffff), 0x80000000); // 2^31 - 1 -> 2^31
  assert.strictEqual(nextPow2(0x80000000), 0x80000000);
});

test('reverseBits32 is an involution and maps 0x80000000 to 1', () => {
  const rng = makeRng(0x1234567);
  for (let i = 0; i < 10000; i++) {
    const x = rng();
    assert.strictEqual(reverseBits32(reverseBits32(x)), x, `x=${x}`);
  }
  for (let x = 0; x <= 0xffff; x++) {
    assert.strictEqual(reverseBits32(reverseBits32(x)), x, `x=${x}`);
  }
  assert.strictEqual(reverseBits32(0x80000000), 1);
});

