'use strict';

// 32-bit bit-twiddling kit. All inputs are treated as uint32.

const U32 = 0xffffffff;

function u32(x) {
  return x >>> 0;
}

// Parallel bit count: the classic 0x55555555 / 0x33333333 / 0x0f0f0f0f dance.
function popcount32(x) {
  x = u32(x);
  x = (x & 0x55555555) + ((x >>> 1) & 0x55555555);
  x = (x & 0x33333333) + ((x >>> 2) & 0x33333333);
  x = (x + (x >>> 4)) & 0x0f0f0f0f;
  // One multiply sums all bytes into the top byte.
  return (Math.imul(x, 0x01010101) >>> 24);
}

// Number of leading zeros, no Math.clz32. Works via a binary search on
// powers of two built with fill-right masks: after m |= m >> k with
// m = ~x & U32... actually simplest correct loop-free form: fold x down.
function nlz(x) {
  x = u32(x);
  if (x === 0) return 32;
  let n = 0;
  if (x <= 0x0000ffff) { n += 16; x <<= 16; }
  if (x <= 0x00ffffff) { n += 8; x <<= 8; }
  if (x <= 0x0fffffff) { n += 4; x <<= 4; }
  if (x <= 0x3fffffff) { n += 2; x <<= 2; }
  if (x <= 0x7fffffff) { n += 1; }
  return n;
}

