'use strict';

// 32-bit bit-twiddling kit. All inputs are treated as uint32.

const U32 = 0xffffffff;

function u32(x) {
  return x >>> 0;
}

// Parallel bit count: the classic 0x55555555 / 0x33333333 / 0x0f0f0f0f dance.
function popcount32(x) {
  x = u32(x);
  x = (x & 0x55555555) + ((x >>> 1) & 0x55555555);
  x = (x & 0x33333333) + ((x >>> 2) & 0x33333333);
  x = (x + (x >>> 4)) & 0x0f0f0f0f;
  // One multiply folds all bytes into the top byte.
  return Math.imul(x, 0x01010101) >>> 24;
}

// Number of leading zeros, computed by folding x toward bit 31
// (no Math.clz32; that's only used to cross-check in tests).
function nlz(x) {
  x = u32(x);
  if (x === 0) return 32;
  let n = 0;
  if (x <= 0x0000ffff) { n += 16; x <<= 16; }
  if (x <= 0x00ffffff) { n += 8; x <<= 8; }
  if (x <= 0x0fffffff) { n += 4; x <<= 4; }
  if (x <= 0x3fffffff) { n += 2; x <<= 2; }
  if (x <= 0x7fffffff) { n += 1; }
  return n;
}

// Power of two iff exactly one bit set.
function isPow2(x) {
  x = u32(x);
  return x !== 0 && (x & (x - 1)) === 0;
}

// Smallest power of two >= x, valid for 1 <= x <= 2^31.
// Fill right then increment.
function nextPow2(x) {
  x = u32(x) - 1;
  x |= x >>> 1;
  x |= x >>> 2;
  x |= x >>> 4;
  x |= x >>> 8;
  x |= x >>> 16;
  return (x + 1) >>> 0;
}

// Reverse all 32 bits via mask-and-shift folding.
function reverseBits32(x) {
  x = u32(x);
  x = ((x & 0x55555555) << 1) | ((x >>> 1) & 0x55555555);
  x = ((x & 0x33333333) << 2) | ((x >>> 2) & 0x33333333);
  x = ((x & 0x0f0f0f0f) << 4) | ((x >>> 4) & 0x0f0f0f0f);
  x = ((x & 0x00ff00ff) << 8) | ((x >>> 8) & 0x00ff00ff);
  return ((x << 16) | (x >>> 16)) >>> 0;
}

module.exports = { U32, u32, popcount32, nlz, isPow2, nextPow2, reverseBits32 };

